        IEnumerator PartDialogClick(WindowsKeyboardProbe input,string id){var view=shell.Root.Q<ScrollView>("modalContent");view.ScrollTo(shell.Root.Q(id));yield return new WaitForSecondsRealtime(.15f);yield return Click(input,id);}
        IEnumerator WaitParts()
        {
            float begin=Time.realtimeSinceStartup,until=begin+45;while(shell.PartBrowser.Entries.Any(e=>NativePartBrowser.Section(e.Definition.category)==NativePartSection.Engine&&!e.Ready)&&Time.realtimeSinceStartup<until)yield return null;
            Check(!shell.PartBrowser.Entries.Any(e=>NativePartBrowser.Section(e.Definition.category)==NativePartSection.Engine&&!e.Ready),"Bounded part calculations finish without a race probe / route "+game.ScreenName+" visible "+shell.Visible+" builds "+shell.PartBrowserBuildCount+" pending "+shell.PartBrowser.Entries.Count(e=>NativePartBrowser.Section(e.Definition.category)==NativePartSection.Engine&&!e.Ready));
            report.AppendLine("Engine-group preview wait: "+(Time.realtimeSinceStartup-begin).ToString("F2")+" s / "+shell.PartBrowser.Entries.Count(e=>NativePartBrowser.Section(e.Definition.category)==NativePartSection.Engine)+" offers");
        }
        void PartDetailLayoutChecks()
        {
            var root=shell.Root;var view=root.Q<ScrollView>("partsDetailScroll");var back=root.Q("partBack");var title=root.Q("partDetailTitle");var actions=root.Q("partDetailActions");
            Check(Math.Abs(back.worldBound.width-40)<.1&&Math.Abs(back.worldBound.height-34)<.1&&title.worldBound.xMin-back.worldBound.xMax>=15,"Detail Back uses the existing shared 40-by-34 style and title gutter");
            Check(root.Q(className:"parts-sources").ClassListContains("hidden")&&root.Q("partsToolbar").ClassListContains("hidden"),"Details omit Shop/Inventory/Installed and browsing tools");
            Check(!string.IsNullOrWhiteSpace(root.Q<Label>("partDescription").text)&&root.Q("partKeySpecs").childCount>0&&root.Q("partDetailFacts").Query<Label>().ToList().Any(l=>l.text=="Compatible"),"Description, key specifications and physical fit status are visible");
            Check(!root.Q<Label>("partDescription").text.Contains("Supplier:")&&!root.Q<Label>("partDescription").text.Contains("Fitment:"),"Main description omits duplicated supplier and internal fitment boilerplate");
            var facts=root.Q("partDetailFacts").worldBound;var dyno=root.Q("partDetailDyno").worldBound;
            Check(facts.xMax<dyno.xMin&&Math.Abs(facts.yMin-dyno.yMin)<1&&dyno.xMax<=view.contentViewport.worldBound.xMax+1,"Facts and dyno use a bounded side-by-side first row");
            Check(root.Q("partQuickStats").Query<VisualElement>(className:"stat-row").ToList().Count==4&&root.Q("partQuickStats").worldBound.yMin>=root.Q("partDetailTop").worldBound.yMax&&root.Q("partStats").worldBound.width>=view.contentViewport.worldBound.width-5,"Four summary bars and detailed comparisons follow the first row at full width");
            Check(actions.GetFirstAncestorOfType<ScrollView>()==null&&actions.worldBound.yMax<=root.Q("footerBar").worldBound.yMin,"Price and cart actions remain outside content scrolling");
        }
        void PartsModelChecks(PlayerProfile p)
